// Generated by vibelang from src/features/runs/metrics.ts; the migrate flow writes it again with each batch.
import { Metric } from "effect";
// Steering's usage metrics in the browser (docs/observability.md#runs), exported over OTLP with the tab's and the engine
// worker's other records. None carries a message.
/** Messages a `run/steer` step queued, by `door` and `outcome` (`kept`, `tab_gone`, `not_kept`). */
export const steersQueued = Metric.counter("smithers_run_steers_queued", {
    description: "Steers queued in the device's outbox, by door and outcome",
    incremental: true,
});
/** Sends of a queued steer, by `outcome` (`taken`, `existing`, `retry`, `refused`). */
export const steerSends = Metric.counter("smithers_run_steer_sends", {
    description: "Steers sent to ChatApi, by outcome",
    incremental: true,
});
